/**
 * Chooses light, dark or the system's mode (`design/components/mode-switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/mode-switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  agentMember,
  borrowedHolder,
  derived,
  handBack,
  lend,
  mountEffect,
  setMode,
  useMember,
  useMode,
  type Emitted,
} from '@polymorph/angular'
import { SegmentedControl, type SegmentedControlProps } from './SegmentedControl'

export interface ModeSwitchMessages {
  /** The segment that pins the light mode: "Light". */
  light: string
  /** The segment that pins the dark mode: "Dark". */
  dark: string
  /** The segment that follows the operating system's mode: "System". */
  system: string
}

/** Chooses light, dark or the system's mode: the inputs it takes, by the React member's prop names. */
export interface ModeSwitchProps {
  disabled?: boolean
  /**
   * The group's accessible name ("Appearance"), because outside a form no FormField names it.
   */
  label: string
  /**
   * Omit for the English defaults; a localized application passes every key.
   */
  messages?: ModeSwitchMessages
  /**
   * SegmentedControl's sizes: it sits in a toolbar, a menu's header or a settings row.
   */
  size?: 'sm' | 'md'
  /**
   * The choice shown, while the application holds it. With it, a choice calls `onChange` and
   * sets no mode. Without it, the ModeSwitch shows the document's preference and sets the mode.
   */
  value?: 'light' | 'dark' | 'system'
}

/** Chooses light, dark or the system's mode. */
@Component({
  selector: 'pm-mode-switch',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  viewProviders: [...lend('mode-switch'), ...handBack()],
  imports: [SegmentedControl],
  // prettier-ignore
  template: `<pm-segmented-control
[options]="e1()"
[value]="e2()"
[label]="e3()"
[size]="e4()"
[disabled]="e5()"
(change)="h1($event)"
></pm-segmented-control>`,
})
export class ModeSwitch {
  readonly disabled = input<
    Exclude<ModeSwitchProps['disabled'], undefined>,
    ModeSwitchProps['disabled']
  >(false, {
    transform: (value: ModeSwitchProps['disabled']) => (value === undefined ? false : value),
  })
  /**
   * The group's accessible name ("Appearance"), because outside a form no FormField names it.
   */
  readonly label = input.required<ModeSwitchProps['label']>()
  /**
   * Omit for the English defaults; a localized application passes every key.
   */
  readonly messages = input<
    Exclude<ModeSwitchProps['messages'], undefined>,
    ModeSwitchProps['messages']
  >((() => ({ light: 'Light', dark: 'Dark', system: 'System' }))(), {
    transform: (value: ModeSwitchProps['messages']) =>
      value === undefined ? (() => ({ light: 'Light', dark: 'Dark', system: 'System' }))() : value,
  })
  /**
   * SegmentedControl's sizes: it sits in a toolbar, a menu's header or a settings row.
   */
  readonly size = input<Exclude<ModeSwitchProps['size'], undefined>, ModeSwitchProps['size']>(
    'md',
    { transform: (value: ModeSwitchProps['size']) => (value === undefined ? 'md' : value) },
  )
  /**
   * The choice shown, while the application holds it. With it, a choice calls `onChange` and
   * sets no mode. Without it, the ModeSwitch shows the document's preference and sets the mode.
   */
  readonly value = input<ModeSwitchProps['value']>(undefined)
  /**
   * The reader's choice. Uncontrolled, it is called after the mode is set.
   */
  readonly onChange = output<'light' | 'dark' | 'system'>({ alias: 'change' })
  protected readonly $ = useMember({
    events: ['change'],
    props: {
      disabled: () => this.disabled(),
      label: () => this.label(),
      messages: () => this.messages(),
      size: () => this.size(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly borrowed = borrowedHolder()
  protected readonly runtime = useMode()
  protected readonly options = derived(() => [
    { value: 'light', label: this.$p.messages.light, icon: 'mode-light' as const },
    { value: 'dark', label: this.$p.messages.dark, icon: 'mode-dark' as const },
    { value: 'system', label: this.$p.messages.system, icon: 'mode-system' as const },
  ])
  protected readonly shown = derived(() => this.$p.value ?? this.runtime().preference)
  protected readonly choose = derived(() => (next: string): void => {
    const picked = next === 'light' || next === 'dark' ? next : 'system'
    if (this.$p.value === undefined) setMode(picked)
    this.$.emit(this.onChange, 'onChange', picked)
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1(): SegmentedControlProps['options'] {
    return this.options.value
  }

  protected e2(): SegmentedControlProps['value'] {
    return this.shown.value
  }

  protected e3(): SegmentedControlProps['label'] {
    return this.$p.label
  }

  protected e4(): SegmentedControlProps['size'] {
    return this.$p.size
  }

  protected e5(): SegmentedControlProps['disabled'] {
    return this.$p.disabled
  }

  protected h1($event: Emitted<SegmentedControl['onChange']>): void {
    this.choose.value($event)
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'ModeSwitch',
      element: () => this.borrowed.element?.(),
      state: () => ({
        value: this.shown.value,
        options: this.options.value.map((option) => ({ id: option.value, label: option.label })),
        disabled: this.$p.disabled,
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => value !== this.shown.value && this.choose.value(value),
        },
      },
      withholds: () => this.borrowed.element?.(),
    })
    this.release1 = () => {
      ran()
    }
  }
}
